// Original synthetic feed; all media is generated by the local integration runner.
export const meta = { id: "fixture.feed", name: "虚构信息流", version: "1.0.0", protocol: 1, allowInsecureHttp: true, defaultHeaders: { "X-Fixture-Token": "local-fixture" } };
export default function(hg) {
  const base = "__FIXTURE_BASE__";
  const direct = { id: "feed:direct", title: "直接入口短片", entryEpisodeId: "entry:real", description: "由 entryEpisodeId 直接播放，无需取详情。" };
  const fallback = { id: "feed:detail", title: "详情入口短片", description: "通过详情与分页获取真实播放列表和分集。" };
  const remember = (method, args) => hg.storage.set("last." + method, args);
  return {
    feed: { async list(args) {
      await remember("feed.list", args);
      if (!args.cursor) return { items: [direct, direct], next: "feed:second" };
      if (args.cursor === "feed:second") {
        if (!await hg.storage.get("secondAttempt")) { await hg.storage.set("secondAttempt", true); throw new hg.PluginError("NETWORK", "虚构分页失败，请重试"); }
        return { items: [direct, fallback], next: "feed:duplicates" };
      }
      return { items: [fallback], next: "feed:duplicates" };
    } },
    media: {
      async getDetail(args) {
        await remember("media.getDetail", args);
        if (args.id === direct.id) throw new Error("Direct entry must not fetch detail during feed playback");
        return { ...fallback, playlists: [{ id: "playlist:real", episodes: [], next: "episodes:cursor" }] };
      },
      async listEpisodes(args) {
        await remember("media.listEpisodes", args);
        return { items: [{ id: "episode:real", index: 42, episodeNumber: 1, label: "真实入口" }], next: null };
      },
      async resolvePlayback(args) {
        await remember("media.resolvePlayback", args);
        if (args.mediaId === direct.id ? args.episodeId !== "entry:real" || args.playlistId !== undefined : args.episodeId !== "episode:real" || args.playlistId !== "playlist:real") throw new Error("Incorrect feed identity");
        return { streams: [{ url: base + "/clip.mp4", format: "progressive" }] };
      },
    },
    progress: { async report(args) { const reports = await hg.storage.get("reports") || []; reports.push(args); await hg.storage.set("reports", reports); } },
    ui: {
      getActions() { return [{ id: "inspect", label: "检查信息流", form: { fields: [] } }]; },
      async submit() { const result = { reports: await hg.storage.get("reports") || [] }; for (const key of await hg.storage.keys("last.")) result[key] = await hg.storage.get(key); return { status: "ok", message: JSON.stringify(result) }; },
    },
  };
}
